function make(text,extra={}){const document=new Y.Doc(),kit=composeExtensions([CoreExtension,createRetainedYjsCollaborationExtension({document,captureTimeout:0,user:{id:'author',name:'Author',color:'#7048e8'},...extra})]),editor=createEditor({schema:kit.schema,plugins:kit.plugins,content:{type:'doc',content:[{type:'paragraph',content:[{type:'text',text}]}]}});cleanup.push(()=>{editor.destroy();document.destroy();});return {document,editor,schema:editor.state.schema};}
